import{_ as d,H as e,f as r,i as a}from"./chunks/framework.B3xCVCEH.js";const h=JSON.parse('{"title":"KBAC Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"dev/security/kbac-threat-model/index.md","filePath":"dev/security/kbac-threat-model/README.md"}'),s={name:"dev/security/kbac-threat-model/index.md"};function i(o,t,n,c,m,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="kbac-threat-model" tabindex="-1">KBAC Threat Model <a class="header-anchor" href="#kbac-threat-model" aria-label="Permalink to &quot;KBAC Threat Model&quot;">​</a></h1><h2 id="server-side-attacks" tabindex="-1">Server-Side Attacks <a class="header-anchor" href="#server-side-attacks" aria-label="Permalink to &quot;Server-Side Attacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Threat</th><th>Specific Attack</th><th>Attack Effort</th><th>Damages</th><th>KBAC Effective?</th><th>Protections in Place</th><th>Mitigations</th><th>Advice</th></tr></thead><tbody><tr><td>User logs in using username/password</td><td>Network Compromised</td><td>Traffic Intercept via MITM</td><td>Medium</td><td>None</td><td>Yes.</td><td>HTTPS for transport, username and password can be used to retreive credentials but not decrypt credentials.</td><td></td><td></td></tr><tr><td>User logs in using username/password</td><td>Network Compromised</td><td>Traffic Intercept via MITM w/Replay Attack</td><td>High</td><td>None</td><td>Yes.</td><td>Randomly salted username/password prevents replay attacks.</td><td></td><td></td></tr><tr><td>Login server is hacked.</td><td>Server Compromised</td><td>&quot;owned&quot; server. (many)</td><td>High</td><td>None</td><td>Yes.</td><td>Login data at rest is encrypted w/keys not on server.</td><td></td><td></td></tr><tr><td>User downloads data from server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is read.</td><td>Medium</td><td>None</td><td>Yes.</td><td>HTTPS for transport, sensitive data is in a (further) encrypted form.</td><td>AES keys randomized for each request. RSA-2048 is strong (as of 2016).</td><td>Subject to NSA-style long term storage attack.</td></tr><tr><td>User downloads data from server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Request is replayed for additional information.</td><td>Medium</td><td>None</td><td>Yes.</td><td>Requests are signed, preventing request being used for any information other than the initially requested information.</td><td></td><td></td></tr><tr><td>User downloads data from server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is manipulated.</td><td>Medium</td><td>None</td><td>Yes.</td><td>Requests are signed, preventing request being used for any information other than the initially requested information. Response data is also signed.</td><td></td><td></td></tr><tr><td>User downloads data from server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is omitted or redirected.</td><td>Medium</td><td>Data is not stored.</td><td>Yes.</td><td>Data is signed and sensitive data is encrypted.</td><td></td><td></td></tr><tr><td>User downloads data from server.</td><td>Server Compromised</td><td>Malicious Server</td><td>High</td><td>Data may be unavailable.</td><td>Yes.</td><td>Data is signed and sensitive data is encrypted. User IP/fingerprints can be acquired for correlation attacks.</td><td></td><td>Subject to NSA-style long term storage attack.</td></tr><tr><td>User uploads data to server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is read.</td><td>Medium</td><td>None</td><td>Yes.</td><td>HTTPS for transport, sensitive data is in a (further) encrypted form.</td><td>AES keys randomized for each request. RSA-2048 is strong (as of 2016).</td><td>Subject to NSA-style long term storage attack.</td></tr><tr><td>User uploads data to server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is read and HTTPS is skimmed or a certificate attack works.</td><td>High</td><td>None</td><td>Yes.</td><td>Sensitive data is in an encrypted form.</td><td>AES keys randomized for each request. RSA-2048 is strong (as of 2016).</td><td>Subject to NSA-style long term storage attack.</td></tr><tr><td>User uploads data to server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Request is replayed to overwrite changes.</td><td>High</td><td>None</td><td>Yes.</td><td>Request signature is timestamped, limiting the viability of this attack to some number of seconds after the initial capture.</td><td></td><td></td></tr><tr><td>User uploads data to server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is manipulated.</td><td>High</td><td>None</td><td>Yes.</td><td>Request signature is timestamped, limiting the viability of this attack to some number of seconds after the initial capture.</td><td></td><td></td></tr><tr><td>User uploads data to server.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is omitted or redirected.</td><td>Medium</td><td>Data is not stored.</td><td>Yes.</td><td></td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is read.</td><td>Medium</td><td>None</td><td>Yes.</td><td>HTTPS for transport, sensitive data is in a (further) encrypted form.</td><td>AES keys randomized for each request. RSA-2048 is strong (as of 2016).</td><td></td></tr><tr><td>User deletes data.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Request is replayed to delete additional material.</td><td>High</td><td>None</td><td>Yes.</td><td>Request signature is timestamped, limiting the viability of this attack to some number of seconds after the initial capture. Request signature also denotes the material to be deleted.</td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is manipulated.</td><td>High</td><td>None</td><td>Yes.</td><td>Request signature is timestamped, limiting the viability of this attack to some number of seconds after the initial capture.</td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Network Compromised</td><td>Traffic Intercept via MITM. Data is omitted or redirected.</td><td>Medium</td><td>Can be aborted, retaining data.</td><td>Yes.</td><td>Data is signed and sensitive data is encrypted.</td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Server Compromised</td><td>Malicious Server</td><td>High</td><td>Can be aborted, retaining data.</td><td>Yes.</td><td>Data is signed and sensitive data is encrypted.</td><td></td><td></td></tr></tbody></table><h2 id="client-side-attacks" tabindex="-1">Client-Side Attacks <a class="header-anchor" href="#client-side-attacks" aria-label="Permalink to &quot;Client-Side Attacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Threat</th><th>Specific Attack</th><th>Attack Effort</th><th>Damages</th><th>KBAC Effective?</th><th>Protections</th><th>Mitigations</th><th>Advice</th></tr></thead><tbody><tr><td>User logs in using username/password</td><td>Client Compromised</td><td>Malicious Browser / Plugin</td><td>Low</td><td>One Person Compromised, cannot use Private Keys any longer. Public key should be blacklisted.</td><td>No.</td><td></td><td>We encourage servers to require HTTP/S which prevents some damages.</td><td></td></tr><tr><td>User logs in using username/password</td><td>Client Compromised</td><td>Worm / Virus / Keylogger</td><td>Low</td><td>One Person Compromised, cannot use Private Keys any longer. Public key should be blacklisted.</td><td>No.</td><td></td><td>Automated login prevents keylogger use.</td><td></td></tr><tr><td>User logs in using username/password</td><td>Website Compromised</td><td>Malicious Javascript</td><td>High</td><td>Every User after server compromised is compromised WRT this system. Usernames and passwords may be sniffed if re-entered. Private Keys may be compromised. Public keys should be blacklisted.</td><td>No.</td><td></td><td>Automated login uses post-hashed credentials, preventing username/password from being reused in other systems.</td><td>Client code should be served from a signed third party (Android application, other application)</td></tr><tr><td>User downloads data from server.</td><td>Client Compromised</td><td>Data altered before viewing on browser. (credentials added, removed, targeted attack)</td><td>High</td><td>Viewed data for compromised client.</td><td>No.</td><td></td><td></td><td>Client code should work in an isolated container, however, this theoretically can still be pierced.</td></tr><tr><td>User downloads data from server.</td><td>Website Compromised</td><td>Data altered before viewing on browser via malicious Javascript.</td><td>High</td><td>Viewed data for any clients who downloads the compromised site.</td><td>No.</td><td></td><td></td><td>Client code should be served from a signed third party (Android application, other application)</td></tr><tr><td>User uploads data to server.</td><td>Client Compromised</td><td>Malicious Browser</td><td>High</td><td>Data can be altered before upload.</td><td>No.</td><td></td><td></td><td></td></tr><tr><td>User uploads data to server.</td><td>Website Compromised</td><td>Malicious Javascript</td><td>High</td><td>Data can be altered via javascript before upload.</td><td>No.</td><td></td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Client Compromised</td><td>Malicious Browser</td><td>High</td><td>Can be aborted, retaining data.</td><td>Yes.</td><td>Data is signed and sensitive data is encrypted.</td><td></td><td></td></tr><tr><td>User deletes data.</td><td>Website Compromised</td><td>Malicious Javascript</td><td>High</td><td>Can be aborted, retaining data.</td><td>Yes.</td><td></td><td></td><td></td></tr></tbody></table>',5)])])}const u=d(s,[["render",i]]);export{h as __pageData,u as default};
